<?php
declare(strict_types=1);
require dirname(__DIR__, 2) . '/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;
Auth::requireAdmin();$pdo=Database::connection();
$mode=in_array((string)($_GET['mode']??'manual'),['manual','automated'],true)?(string)$_GET['mode']:'manual';$showArchived=Auth::isSuperAdmin()&&($_GET['archived']??'0')==='1';$createError=(string)($_SESSION['scoring_create_error']??'');unset($_SESSION['scoring_create_error']);
$events=$pdo->query("SELECT e.id,e.name,e.event_date FROM bdc_events e LEFT JOIN bdc_scoring_archived_events a ON a.event_id=e.id WHERE e.status NOT IN ('completed','published') AND a.event_id IS NULL ORDER BY e.event_date DESC,e.name")->fetchAll();
$duplicateEvents=$pdo->query("SELECT DISTINCT e.id,e.name,e.event_date,e.status FROM bdc_events e JOIN bdc_scoring_rounds r ON r.event_id=e.id WHERE r.status<>'archived' ORDER BY e.event_date DESC,e.name")->fetchAll();
$occupied=$pdo->query("SELECT DISTINCT event_id,dance_style,division FROM bdc_scoring_rounds WHERE status<>'archived'")->fetchAll();
$roundStatusSql=$showArchived?"r.status='archived'":"r.status<>'archived'";$stmt=$pdo->prepare("SELECT r.*,e.name event_name,e.event_date,e.status event_status,(SELECT COUNT(*) FROM bdc_scoring_entries x WHERE x.round_id=r.id) entry_count,(SELECT COUNT(*) FROM bdc_scoring_judges x WHERE x.round_id=r.id) judge_count,(SELECT COUNT(*) FROM bdc_scoring_marks x WHERE x.round_id=r.id) mark_count,(SELECT COUNT(*) FROM bdc_scoring_final_marks x WHERE x.round_id=r.id) final_mark_count FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id LEFT JOIN bdc_scoring_archived_events a ON a.event_id=e.id WHERE e.status NOT IN ('completed','published') AND a.event_id IS NULL AND {$roundStatusSql} AND r.scoring_mode=:mode ORDER BY COALESCE(r.archived_at,r.updated_at) DESC LIMIT 100");
$stmt->execute(['mode'=>$mode]);$rounds=$stmt->fetchAll();$archivedCountStmt=$pdo->prepare("SELECT COUNT(*) FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id LEFT JOIN bdc_scoring_archived_events a ON a.event_id=e.id WHERE e.status NOT IN ('completed','published') AND a.event_id IS NULL AND r.status='archived' AND r.scoring_mode=:mode");$archivedCountStmt->execute(['mode'=>$mode]);$archivedCount=(int)$archivedCountStmt->fetchColumn();$csrf=Csrf::token();
?>
