<div class="card shadow-sm mb-4 border-primary"><div class="card-body"><div class="row g-3 align-items-end"><div class="col-lg-8"><h2 class="h5 mb-1">Duplicate Jack &amp; Jill Event</h2><p class="text-muted mb-2">Copies the event setup, competitors and judges into a fresh Draft. Scores, results, approvals and live state are never copied.</p><form method="post" action="duplicate-event.php" class="row g-2" onsubmit="return confirm('Duplicate this event with competitors and judges, but without scores or results?');"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="mode" value="<?=e($mode)?>"><div class="col-md-8"><select class="form-select" name="event_id" required><option value="">Choose event to duplicate</option><?php foreach($duplicateEvents as $event):?><option value="<?=(int)$event['id']?>"><?=e(($event['event_date']?:'Date pending').' — '.$event['name'].' · '.ucfirst((string)$event['status']))?></option><?php endforeach;?></select></div><div class="col-md-4"><button class="btn btn-primary w-100">Duplicate Event</button></div></form></div></div></div></div>
