<form method="post" action="index.php?mode=<?=e($mode)?>" class="row g-3"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="create_round"><input type="hidden" name="scoring_mode" value="<?=e($mode)?>">
<div class="col-lg-6"><label class="form-label">Select Existing Event</label><select class="form-select" name="event_id" id="eventId"><option value="">Select event</option><?php foreach($events as $event):?><option value="<?=(int)$event['id']?>"><?=e(($event['event_date']?:'Date pending').' — '.$event['name'])?></option><?php endforeach;?></select></div>
<div class="col-lg-3"><label class="form-label">Dance Style</label><select class="form-select" name="dance_style" id="danceStyle"><option value="bachata">Bachata</option><option value="salsa">Salsa</option></select></div>
<div class="col-lg-3"><label class="form-label">Division</label><select class="form-select" name="division" id="division"><option value="novice">Novice</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option><option value="bachata_rising" data-dance="bachata">Bachata Rising</option><option value="bachata_open" data-dance="bachata">Bachata Open</option><option value="bachata_invitational" data-dance="bachata">Bachata Invitational</option><option value="salsa_rising" data-dance="salsa">Salsa Rising</option><option value="salsa_open" data-dance="salsa">Salsa Open</option><option value="salsa_invitational" data-dance="salsa">Salsa Invitational</option></select><div id="occupiedNote" class="form-text text-danger d-none">This scoring workflow already exists. Open it under Saved Rounds or delete the Draft to restart.</div></div>
<div class="col-12 text-center text-muted fw-semibold">OR CREATE A BASIC EVENT</div><div class="col-lg-8"><label class="form-label">New Event Name</label><input class="form-control" name="new_event_name" maxlength="190"></div><div class="col-lg-4"><label class="form-label">Event Date</label><input class="form-control" type="date" name="new_event_date"></div><div class="col-lg-4"><label class="form-label">Round Date &amp; Time</label><input class="form-control" type="datetime-local" name="scheduled_at"><div class="form-text">Schedule for the selected Heats or Final.</div></div><div class="col-12"><button class="btn btn-success createBtn" name="round_type" value="heats">Start with Heats</button> <button class="btn btn-dark createBtn" name="round_type" value="final">Go Straight to Final</button></div></form></div></div>
<div class="card shadow-sm"><div class="card-body"><div class="d-flex justify-content-between align-items-center gap-3 mb-2"><div class="d-flex align-items-center gap-2"><h2 class="h5 mb-0"><?=$showArchived?'Archived Rounds':'Saved Rounds'?></h2><?php if(Auth::isSuperAdmin()):?><a class="btn btn-sm <?=$showArchived?'btn-dark':'btn-outline-secondary'?>" href="?mode=<?=e($mode)?><?=$showArchived?'':'&amp;archived=1'?>"><?=$showArchived?'Back to Saved Rounds':'Archived Rounds ('.$archivedCount.')'?></a><?php endif;?></div><details class="column-picker"><summary class="btn btn-sm btn-outline-secondary">Columns ▾</summary><div class="column-picker-menu"><div class="small fw-semibold text-uppercase text-muted mb-2">Show columns</div><?php foreach(['event_date'=>'Event Date','round_schedule'=>'Round Schedule','dance'=>'Dance','division'=>'Division','round'=>'Round','status'=>'Status','updated'=>'Updated','actions'=>'Actions'] as $key=>$label):?><label class="form-check mb-2"><input class="form-check-input saved-column-toggle" type="checkbox" value="<?=e($key)?>"><span class="form-check-label"><?=e($label)?></span></label><?php endforeach;?><div class="d-flex gap-2 border-top pt-2 mt-2"><button type="button" class="btn btn-sm btn-outline-dark saved-columns-all">Show All</button><button type="button" class="btn btn-sm btn-link saved-columns-reset">Reset</button></div></div></details></div><div class="table-responsive"><table class="table align-middle saved-rounds-table"><thead><tr><th data-col="event">Event</th><th data-col="event_date">Event Date</th><th data-col="round_schedule">Round Schedule</th><th data-col="dance">Dance</th><th data-col="division">Division</th><th data-col="round">Round</th><th data-col="status">Status</th><th data-col="updated">Updated</th><th data-col="actions" class="text-end">Actions</th></tr></thead><tbody>
<?php if(!$rounds):?><tr><td colspan="9" class="text-center text-muted py-4"><?=$showArchived?'No archived scoring rounds.':'No active scoring rounds.'?></td></tr><?php else:foreach($rounds as $r):$draft=in_array((string)$r['status'],['draft','discarded'],true);$hasScores=(int)$r['mark_count']>0||(int)$r['final_mark_count']>0;$dataCount=(int)$r['entry_count']+(int)$r['judge_count']+(int)$r['mark_count']+(int)$r['final_mark_count'];?><tr><td data-col="event"><?=e($r['event_name'])?></td><td data-col="event_date" class="text-nowrap"><?=e($r['event_date']?date('d M Y',strtotime((string)$r['event_date'])):'Date pending')?></td><td data-col="round_schedule" class="text-nowrap"><?=e(!empty($r['scheduled_at'])?date('d M Y, g:i A',strtotime((string)$r['scheduled_at'])):'Not scheduled')?></td><td data-col="dance"><span class="badge text-bg-secondary"><?=e(ucfirst($r['dance_style']??'bachata'))?></span></td><td data-col="division"><?=e(ucwords(str_replace('_',' ',$r['division'])))?></td><td data-col="round"><?=e(ucfirst($r['round_type']))?></td><td data-col="status"><span class="badge text-bg-secondary"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></span><?php if($draft&&$dataCount>0):?><div class="small text-warning-emphasis">Contains scoring setup</div><?php endif;?></td><td data-col="updated"><?=e($r['updated_at'])?></td><td data-col="actions" class="text-end"><div class="d-inline-flex gap-2"><?php if(!$showArchived):?><a class="btn btn-sm btn-outline-dark" href="index.php?mode=<?=e($r['scoring_mode'])?>&amp;round_id=<?=(int)$r['id']?>">Open</a><?php if($draft&&!$hasScores):?><a class="btn btn-sm btn-outline-primary" href="edit-draft.php?mode=<?=e($r['scoring_mode'])?>&amp;round_id=<?=(int)$r['id']?>">Edit Draft Details</a><?php endif;?><?php if($draft&&Auth::isSuperAdmin()):?><form method="post" action="delete-draft.php"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="event_id" value="<?=(int)$r['event_id']?>"><input type="hidden" name="dance_style" value="<?=e($r['dance_style']??'bachata')?>"><input type="hidden" name="division" value="<?=e($r['division'])?>"><input type="hidden" name="mode" value="<?=e($mode)?>"><button class="btn btn-sm btn-outline-danger">Delete Draft</button></form><?php endif;?><?php endif;?><?php if(Auth::isSuperAdmin()):?><form method="post" action="archive-round.php" onsubmit="return confirm('<?=$showArchived?'Restore this scoring round to its previous status?':'Archive this scoring round? All setup and scoring data will be preserved.'?>');"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="round_id" value="<?=(int)$r['id']?>"><input type="hidden" name="data_mode" value="live"><input type="hidden" name="mode" value="<?=e($mode)?>"><input type="hidden" name="archive_action" value="<?=$showArchived?'restore':'archive'?>"><button class="btn btn-sm <?=$showArchived?'btn-outline-success':'btn-outline-secondary'?>"><?=$showArchived?'Restore':'Archive'?></button></form><?php endif;?></div></td></tr><?php endforeach;endif;?></tbody></table></div></div></div></main>
<script>const occupied=<?=json_encode($occupied,JSON_UNESCAPED_SLASHES)?>,ev=document.getElementById('eventId'),d=document.getElementById('danceStyle'),v=document.getElementById('division'),note=document.getElementById('occupiedNote'),buttons=[...document.querySelectorAll('.createBtn')];function sync(){[...v.options].forEach(o=>{const only=o.dataset.dance;o.hidden=!!only&&only!==d.value;o.disabled=!!only&&only!==d.value});const allowed=d.value==='salsa'?['novice','intermediate','advanced','salsa_rising','salsa_open','salsa_invitational']:['novice','intermediate','advanced','bachata_rising','bachata_open','bachata_invitational'];if(!allowed.includes(v.value))v.value='novice';const hit=ev.value&&occupied.some(x=>String(x.event_id)===ev.value&&(x.dance_style||'bachata')===d.value&&x.division===v.value);note.classList.toggle('d-none',!hit);buttons.forEach(b=>b.disabled=!!hit)}[ev,d,v].forEach(x=>x.addEventListener('change',sync));sync();</script></body></html>
